import os,json,base64,pathlib,urllib.request
p=pathlib.Path(__file__).resolve().parent
reference=base64.b64decode("")
(p/"source_reference_thumbnail.jpg").write_bytes(reference)
current=base64.b64encode((p/"renders"/"closed_front.png").read_bytes()).decode()
prompt="""Compare these two actual images visually. FIRST image is the USER'S TARGET reference, the second is CURRENT Blender render of CAD. User demands the CAD assembly to visually match FIRST, not synthetic generated image. Describe the top 3 geometric mismatches with specificity, and provide an implementable engineering change to each that preserves an actual mechanical proof of concept. Current model has 9 stations with a functional 5mm shaft rotation and rack, all actual CadQuery; current full body height ~103mm and width384mm, support foot Ø132mm. Major shape difference is fan-like shards (zigzags) rather than large smooth overlapping elliptical bowl scales; central dark spine still enormous compared target slender horizontal tubular rod. Cross section of upper and lower metal leaves should be physical sheets rather than invented glowing graphics. Need practical mechanism still, shaft axis rotates about Y and neighboring shaft clearance 5.6mm at last validation. Do not claim exact match without verification. Reply in 7 concise paragraphs no code, and tell us minimum real-CAD changes, not material cheats.
"""
body={"model":"gpt-6.2-astra","reasoning":{"effort":"high"},"max_output_tokens":5500,"input":[{"role":"user","content":[{"type":"input_text","text":prompt},{"type":"input_image","image_url":"data:image/jpeg;base64,"+base64.b64encode(reference).decode()},{"type":"input_image","image_url":"data:image/png;base64,"+current}]}]}
try:
 req=urllib.request.Request("https://api.openai.com/v1/responses",data=json.dumps(body).encode(),headers={"Authorization":"Bearer "+os.environ["OPENAI_API_KEY"],"Content-Type":"application/json"},method="POST")
 with urllib.request.urlopen(req,timeout=230) as res:data=json.load(res)
 s="\n".join(q.get("text","") for row in data.get("output",[]) for q in row.get("content",[]) if q.get("type")=="output_text")
 (p/"astra_actual_reference_review.md").write_text(s,encoding="utf-8")
 print("model",data.get("model"),"status",data.get("status"),"chars",len(s),"usage",data.get("usage"),flush=True)
except Exception as e: print("ERROR",type(e).__name__,str(e)[:400],flush=True)
